/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.OptionalInt;
import java.util.regex.Pattern;

/**
 * Order of the versions of a source ({@code service.version}), to know when an error comes from a
 * newer release. Numeric versions ({@code 1.4.2}, {@code v2.0}, {@code 1.0.0-SNAPSHOT},
 * {@code 2026.11.12}) are compared part by part, and a pre-release ({@code -SNAPSHOT},
 * {@code -rc.1}) goes before its release. Other versions (commit hashes) are only equal or
 * different: a different one counts as later, since its order is unknown.
 */
public final class Releases {

  private static final Pattern NUMERIC = Pattern.compile("\\d+(\\.\\d+)*");

  private Releases() {}

  /**
   * @return true if an error seen in {@code candidate} is newer than {@code baseline}; without one
   *         of them it cannot be told, so it is true (the issue reopens as before the versions)
   */
  public static boolean isAfter(final String candidate, final String baseline) {
    if (blank(candidate) || blank(baseline)) {
      return true;
    }
    OptionalInt order = compare(candidate, baseline);
    return order.isPresent() ? order.getAsInt() > 0 : !candidate.trim().equals(baseline.trim());
  }

  /** The order of two versions, or empty when they cannot be ordered. */
  public static OptionalInt compare(final String a, final String b) {
    String[] left = split(a);
    String[] right = split(b);
    if (null == left || null == right) {
      return a.trim().equals(b.trim()) ? OptionalInt.of(0) : OptionalInt.empty();
    }
    String[] numbersA = left[0].split("\\.");
    String[] numbersB = right[0].split("\\.");
    for (int i = 0; i < Math.max(numbersA.length, numbersB.length); i++) {
      long x = i < numbersA.length ? Long.parseLong(numbersA[i]) : 0;
      long y = i < numbersB.length ? Long.parseLong(numbersB[i]) : 0;
      if (x != y) {
        return OptionalInt.of(Long.compare(x, y));
      }
    }
    // Same numbers: the release goes after its pre-releases
    if (left[1].isEmpty() || right[1].isEmpty()) {
      return OptionalInt.of(Boolean.compare(left[1].isEmpty(), right[1].isEmpty()));
    }
    return OptionalInt.of(Integer.signum(left[1].compareToIgnoreCase(right[1])));
  }

  /**
   * {numbers, pre-release} or null if it is not a numeric version; the build ({@code +...}) is
   * ignored.
   */
  private static String[] split(final String version) {
    String value = version.trim();
    if (value.startsWith("v") || value.startsWith("V")) {
      value = value.substring(1);
    }
    int plus = value.indexOf('+');
    if (plus >= 0) {
      value = value.substring(0, plus);
    }
    int dash = value.indexOf('-');
    String numbers = dash >= 0 ? value.substring(0, dash) : value;
    String pre = dash >= 0 ? value.substring(dash + 1) : "";
    return NUMERIC.matcher(numbers).matches() ? new String[] {numbers, pre} : null;
  }

  private static boolean blank(final String value) {
    return null == value || value.isBlank();
  }
}
